def build_song_objects():
    songs = []
    for title, artist, genre, duration, audio_url in SONGS_WITH_AUDIO:
        songs.append({
            "title": title,
            "artist": artist,
            "genre": genre,
            "duration": duration,
            "audio_url": audio_url,
        })
    return songs
